out=arr.copy()
for r in range(arr.shape[0]):
    cs=np.where(arr[r]==8)[0]
    if len(cs)>=2: out[r,cs.min():cs.max()+1]=np.where(arr[r,cs.min():cs.max()+1]==8,8,2)
for c in range(arr.shape[1]):
    rs=np.where(arr[:,c]==8)[0]
    if len(rs)>=2: out[rs.min():rs.max()+1,c]=np.where(arr[rs.min():rs.max()+1,c]==8,8,2)
print(out.tolist())
